loginUrl:
openBrowser = () => {
    java.startBrowser('https://www.pilisf.com', '过完验证后，务必等到首页完全显示，再返回阅读');
}

checkCookie = () => {
    try {
        var c = java.getCookie('https://www.pilisf.com') || '';
        var hasClearance = c.indexOf('cf_clearance') !== -1;
        var hasBm = c.indexOf('__cf_bm') !== -1;
        java.toast('cf_clearance: ' + (hasClearance ? '✅' : '❌') + '  __cf_bm: ' + (hasBm ? '✅' : '❌'));
    } catch(e) {
        java.toast('检查失败: ' + e);
    }
}

clearCookie = () => {
    try {
        java.clearCookie('https://www.pilisf.com');
        java.toast('🗑️ Cookie 已清除，需重新过 CF 验证');
    } catch(e) {
        java.toast('清 Cookie 失败: ' + e);
    }
}

